{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Cancer is a complex, multilevel phenomenon [1-5] in which health outcomes depend on highly interrelated elements across stages of etiology, prevention, screening, diagnosis, treatment, survivorship, and end-of-life care [6, 7]. Standard bench and clinical research approaches alone are not well suited to account for this complexity, as most cancer control interventions often focus on explicit, often linear health outcomes of a specific, well-defined population [1, 8, 9].",
      "reason": "The introduction describes the current state of knowledge about cancer as a complex, multilevel phenomenon and explains limitations and uncertainties of standard research approaches, establishing important uncertainties relevant to the review."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "In a 2019 report, the National Academies of Sciences, Engineering, and Medicine argued that systems science methods could help illustrate the multilevel nature of cancer effects and costs to society and help cancer control efforts be more agile and adaptive [7]. The Journal of the National Cancer Institute published several reports calling for the use of complex, multilevel, or systems-focused approaches to advance the landscape of cancer prevention and control [1, 2, 10]. Systems models, particularly well calibrated simulation models, provide a relatively lowcost and low-risk opportunity for comparing potential interventions or treatments in silico before involving busy clinics and patients in trials [1, 7, 11, 12]. ... The extent to which system dynamics modeling has been applied specifically to cancer prevention and control has not been studied.",
      "reason": "The introduction explains the importance and need for the review by citing authoritative calls for systems approaches, describing the potential benefits of system dynamics models, and stating that the extent of their application to cancer prevention and control has not been studied."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PARTIAL",
      "chunk_id": "text_3",
      "quote": "Although system dynamics modeling has been utilized in various aspects of public health since the 1970s, past reviews in this field have noted a significant increase in their use since the early 2000s, especially in areas focused on chronic or non-communicable diseases [24, 25]. The extent to which system dynamics modeling has been applied specifically to cancer prevention and control has not been studied.",
      "reason": "The authors reference past reviews in the broader field and note a gap (no study of application to cancer prevention/control), but do not explicitly identify or cite a previous similar systematic review that the current review updates or why an update/replication is needed; thus only partially addresses the conditional item."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review is a methods review of system dynamics modeling for cancer prevention and control and does not focus on reviews of intervention effects; the Methods section states the review \"did not assess health outcomes,\" so describing an intervention's mechanism is not applicable."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review synthesizes applications of system dynamics modeling rather than evaluating complex interventions or delivery contexts; there is no indication a logic model was relevant or required for this methods-focused review."
    }
  ],
  "confidence": "85"
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "System dynamics modeling, which consists of diagramming and simulation approaches for understanding and managing such complexity, is being increasingly applied to cancer prevention and control, but the breadth, characteristics, and quality of these studies is not known.",
      "reason": "The abstract explicitly states the review aim to assess the breadth, characteristics, and quality of system dynamics studies applied to cancer prevention and control, which constitutes a clear objective for the review."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_5",
      "quote": "A formal research protocol was not created for this review. The study was not registered in the International Prospective Register of Systematic Reviews (PROSPERO) as it was a methods review and did not assess health outcomes.",
      "reason": "The review is a methods review that did not assess health outcomes or intervention effects, so PICO-style planned comparisons are not applicable."
    }
  ],
  "confidence": "90"
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PARTIAL",
      "chunk_id": "text_7",
      "quote": "Included articles: 1) were published in peer-reviewed journals; 2) were written in English; 3) used system dynamics modeling (i.e., causal-loop diagramming, stock-and-flow diagramming, or computational system dynamics modeling); 4) pertained to cancer prevention or control; and 4) were published within the last 10 years.",
      "reason": "The manuscript specifies several study-level eligibility characteristics (publication type, language, modeling approach, topical focus, and publication timeframe). It does not, however, specify other study-characteristics requested by the criterion such as eligible study designs in detail, settings, or follow-up requirements, so the element is only partially met."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "Included articles: 1) were published in peer-reviewed journals; 2) were written in English; ... and 4) were published within the last 10 years.",
      "reason": "The review explicitly states report-level eligibility criteria including publication venue (peer-reviewed journals), language (English), and publication year restrictions (last 10 years)."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence was found distinguishing exclusion due to outcomes not being measured versus exclusion due to outcome results not being reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PARTIAL",
      "chunk_id": "text_10",
      "quote": "As shown in Fig 1, most studies included a computational system dynamics simulation model (n = 21; 66%), while the remaining studies (n = 11; 34%) used only diagramming approaches (referred to as diagram-only studies in this review).",
      "reason": "The review specifies groups used in analyses (simulation vs diagram-only) and gives counts, satisfying part of the requirement. However, it does not explicitly link these groups to specific comparisons defined in the review objectives (no explicit statement mapping syntheses/groups to prespecified comparisons), so the requirement is only partially satisfied."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "This search period was selected to reflect recent developments and current applications of system dynamics modeling related to cancer.",
      "reason": "The manuscript provides a rationale for the notable restriction on publication year (last 10 years). Additional related rationale for exclusions (e.g., excluding studies not including cancer or those focused solely on pathogenesis) is provided in the Limitations section (text_20), supporting that restrictions were justified."
    }
  ],
  "confidence": "80"
}

